<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoProvincia, guardarProvincia, listarDepartamentosActivos, listarProvincias } from '../services/provincias'
import type { DepartamentoOption, Provincia, ProvinciaPayload } from '../interfaces/provincias.interface'

const rows=ref<Provincia[]>([]),departments=ref<DepartamentoOption[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive<ProvinciaPayload>({departamento_id:null,ubigeo:'',nombre:''})
const message=(value:unknown)=>value instanceof Error?value.message:'No se pudo completar la operación.'

async function load(next=1){loading.value=true;error.value='';try{const response=await listarProvincias(criterio.value,next);rows.value=response.data;page.value=response.current_page;lastPage.value=response.last_page;total.value=response.total}catch(value){error.value=message(value)}finally{loading.value=false}}
async function loadDepartments(){try{departments.value=await listarDepartamentosActivos()}catch(value){error.value=message(value)}}
async function open(item?:Provincia){editing.value=item?.id??null;Object.assign(form,{departamento_id:item?.departamento_id??null,ubigeo:item?.ubigeo??'',nombre:item?.nombre??''});error.value='';modal.value=true;if(!departments.value.length)await loadDepartments()}
async function save(){const ubigeo=form.ubigeo.trim().toUpperCase(),nombre=form.nombre.trim().toUpperCase();if(!form.departamento_id)return void(error.value='Debe seleccionar un departamento.');if(!ubigeo)return void(error.value='El código ubigeo es obligatorio.');if(ubigeo.length>10)return void(error.value='El código ubigeo admite como máximo 10 caracteres.');if(nombre.length<3)return void(error.value='El nombre debe tener al menos 3 caracteres.');saving.value=true;error.value='';try{await guardarProvincia(editing.value,{departamento_id:form.departamento_id,ubigeo,nombre});modal.value=false;success.value=`Provincia ${editing.value?'actualizada':'registrada'} correctamente.`;await load(editing.value?page.value:1)}catch(value){error.value=message(value)}finally{saving.value=false}}
async function toggle(item:Provincia){const action=item.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} la provincia ${item.nombre}?`))return;error.value='';try{const response=await cambiarEstadoProvincia(item.id);item.estado=response.estado;success.value=response.message??`Provincia ${item.estado?'activada':'desactivada'} correctamente.`}catch(value){error.value=message(value)}}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Provincias</nav><header class="hero"><div class="mark">PR</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Provincias</h1><p>Catálogo provincial organizado por departamento y código de ubigeo.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nueva provincia</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><label>Buscar por ubigeo, nombre o departamento<input v-model.trim="criterio" placeholder="Ej. 1501, LIMA o CALLAO"></label><button>Buscar</button><button type="button" class="soft" @click="criterio='';load(1)">Limpiar</button></form>
<section class="table-card"><header><div><small>MAESTRO DE UBIGEO</small><h2>Provincias registradas</h2></div></header><div v-if="loading" class="empty">Consultando provincias…</div><div v-else-if="!rows.length" class="empty">No se encontraron provincias.</div><div v-else class="scroll"><table><thead><tr><th>#</th><th>Departamento</th><th>Ubigeo</th><th>Nombre</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>{{item.id}}</td><td>{{item.departamento?.nombre??'—'}}</td><td><b>{{item.ubigeo}}</b></td><td>{{item.nombre}}</td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button :class="item.estado?'disable':'enable'" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">PR</div><div><small>MAESTRO DE UBIGEO</small><h2>{{editing?'Editar':'Registrar'}} provincia</h2></div><button type="button" @click="modal=false">×</button></header><label>Departamento *<select v-model="form.departamento_id" required><option :value="null">Seleccione un departamento</option><option v-for="department in departments" :key="department.id" :value="department.id">{{department.nombre}} ({{department.ubigeo}})</option></select></label><div class="grid"><label>Código ubigeo *<input v-model="form.ubigeo" maxlength="10" @input="form.ubigeo=form.ubigeo.toUpperCase()"></label><label>Nombre *<input v-model="form.nombre" maxlength="150" @input="form.nombre=form.nombre.toUpperCase()"></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>

<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#fff0f5;font-size:.52rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:13px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label{margin-right:auto;width:min(440px,100%);font-size:.52rem}.filters input,.dialog input,.dialog select{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.54rem}th,td{padding:10px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}.active,.inactive{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.44rem}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(650px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:10px;font-size:.5rem}.grid{display:grid;grid-template-columns:1fr 2fr;gap:9px}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:760px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%}.grid{grid-template-columns:1fr}.actions{min-width:140px}}
</style>
